import { about, profile, skills } from "@/content/site";

export function About() {
  return (
    <section id="about" className="px-6 py-20 sm:px-10">
      <div className="mx-auto grid w-full max-w-4xl gap-12 sm:grid-cols-[1fr_2fr]">
        <div>
          <h2 className="text-sm uppercase tracking-[0.18em] text-foreground/50">About</h2>
          <p className="mt-3 text-foreground/60">
            {profile.location}
            <br />
            {profile.yearsExperience}+ years experience
          </p>
        </div>
        <div className="space-y-5 text-foreground/80 leading-relaxed">
          {about.map((p, i) => (
            <p key={i}>{p}</p>
          ))}
          <ul className="flex flex-wrap gap-2 pt-4">
            {skills.map((s) => (
              <li
                key={s}
                className="rounded-full border border-foreground/15 px-3 py-1 text-xs text-foreground/70"
              >
                {s}
              </li>
            ))}
          </ul>
        </div>
      </div>
    </section>
  );
}

import { experience } from "@/content/site";

export function Experience() {
  return (
    <section id="experience" className="px-6 py-20 sm:px-10">
      <div className="mx-auto w-full max-w-4xl">
        <h2 className="text-sm uppercase tracking-[0.18em] text-foreground/50">Experience</h2>
        <ol className="mt-8 space-y-12 border-l border-foreground/10 pl-6 sm:pl-8">
          {experience.map((e, i) => (
            <li key={i} className="relative">
              <span
                className="absolute -left-[33px] top-2 h-2 w-2 rounded-full bg-foreground/40 sm:-left-[37px]"
                aria-hidden
              />
              <div className="flex flex-wrap items-baseline justify-between gap-x-4 gap-y-1">
                <h3 className="text-lg font-medium">
                  {e.role}{" "}
                  <span className="text-foreground/60">@ {e.company}</span>
                </h3>
                <p className="text-sm text-foreground/50">
                  {e.start} — {e.end}
                </p>
              </div>
              <ul className="mt-3 space-y-2 text-foreground/75 leading-relaxed">
                {e.bullets.map((b, j) => (
                  <li key={j}>{b}</li>
                ))}
              </ul>
              {(e.highlight || e.reference) && (
                <p className="mt-3 text-xs text-foreground/45">
                  {e.highlight && (
                    <span className="mr-3">
                      <span className="font-medium text-foreground/60">Highlight:</span> {e.highlight}
                    </span>
                  )}
                  {e.reference && (
                    <span>
                      <span className="font-medium text-foreground/60">Reference:</span> {e.reference}
                    </span>
                  )}
                </p>
              )}
            </li>
          ))}
        </ol>
      </div>
    </section>
  );
}

